class Solution:
    def removeKBalancedSubstrings(self, s: str, k: int) -> str:
        good = '(' * k + ')' * k
        while True:
            out = []; i = 0; removed = False
            while i < len(s):
                if s.startswith(good, i):
                    i += 2 * k; removed = True
                else:
                    out.append(s[i]); i += 1
            s = ''.join(out)
            if not removed:
                return s

