        while (true) {
            string out; bool removed = false;
            for (int i = 0; i < (int)s.size();) {
                if (s.compare(i, 2*k, good) == 0) { i += 2*k; removed = true; }
                else out += s[i++];
            }
            s = out;
            if (!removed) return s;
        }
    }
};

