class Solution:
    def removeKBalancedSubstrings(self, s: str, k: int) -> str:
        st = []
        for ch in s:
            if ch == ')' and len(st) >= k and all(c == '(' for c in st[-k:]):
                del st[-k:]
            else:
                st.append(ch)
        return ''.join(st)

