class Solution {
public:
    string removeKBalancedSubstrings(string s, int k) {
        string st;
        for (char ch : s) {
            if (ch == ')' && (int)st.size() >= k
                && st.substr(st.size() - k) == string(k, '(')) {
                st.resize(st.size() - k);
            } else st += ch;
        }
        return st;
    }
};

