class Solution {
    public String removeKBalancedSubstrings(String s, int k) {
        StringBuilder st = new StringBuilder();
        for (char ch : s.toCharArray()) {
            int len = st.length();
            boolean match = ch == ')' && len >= k;
            if (match) for (int i = len - k; i < len; i++)
                if (st.charAt(i) != '(') { match = false; break; }
            if (match) st.setLength(len - k);
            else st.append(ch);
        }
        return st.toString();
    }
}

